149→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
150→	cfg := &runConfig{Model: defaultDroidModel}
151→	for _, o := range opts {
152→		o(cfg)
153→	}
154→
155→	model := cfg.Model
156→	if model == "" {
157→		model = defaultDroidModel
158→	}
159→
160→	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
161→	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
162→
163→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
164→	cmd.Dir = dir
165→	cmd.Stdin = nil
166→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
167→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
168→	cmd.Cancel = func() error {
169→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
170→	}
171→	cmd.WaitDelay = 5 * time.Second
172→
173→	var stdout, stderr strings.Builder
174→	cmd.Stdout = &stdout
175→	cmd.Stderr = &stderr
176→
177→	err := cmd.Run()
