201→	for attempt := range maxAttempts {
202→		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
203→		var err error
204→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
205→		if err != nil {
206→			return nil, err
207→		}
208→
209→		// Wait for the interactive prompt indicator.
210→		if _, err := s.WaitFor(d.PromptPattern(), 30*time.Second); err != nil {
211→			_ = s.Close()
212→			if attempt < maxAttempts-1 {
213→				lastErr = err
214→				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed: %s\n", attempt+1, maxAttempts, err)
215→				continue
216→			}
217→			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", maxAttempts, err)
218→		}
219→		s.stableAtSend = ""
220→		return s, nil
221→	}
