110→		// Best-effort merge: ignore parse errors and start fresh
111→		_ = json.Unmarshal(data, &settings)
112→	}
113→
114→	// Replace or add the BYOK model entry.
115→	byokModel := droidCustomModel{
116→		DisplayName:    droidCustomModelDisplayName,
117→		Model:          droidCustomModelBaseID,
118→		BaseURL:        "https://api.anthropic.com",
119→		APIKey:         apiKey,
120→		Provider:       "anthropic",
121→		MaxOutputToken: 8192,
122→	}
123→
124→	found := false
125→	for i, m := range settings.CustomModels {
126→		if m.Model == byokModel.Model {
127→			settings.CustomModels[i] = byokModel
128→			found = true
129→			break
130→		}
131→	}
132→	if !found {
133→		settings.CustomModels = append(settings.CustomModels, byokModel)
134→	}
135→
136→	// Set the BYOK model as the default for interactive mode.
137→	if settings.SessionDefaultSettings == nil {
138→		settings.SessionDefaultSettings = &droidSessionDefaults{}
139→	}
140→	settings.SessionDefaultSettings.Model = droidCustomModelBaseID
141→
142→	data, err := json.MarshalIndent(settings, "", "  ")
143→	if err != nil {
144→		return fmt.Errorf("marshal settings: %w", err)
145→	}
146→	return os.WriteFile(settingsPath, data, 0o644)
147→}
