 29→	return func(c *runConfig) { c.PermissionMode = mode }
 30→}
 31→
 32→func WithPromptTimeout(d time.Duration) Option {
 33→	return func(c *runConfig) { c.PromptTimeout = d }
 34→}
 35→
 36→type Agent interface {
 37→	Name() string
 38→	// Binary returns the CLI binary name (e.g. "claude", "gemini").
 39→	Binary() string
 40→	EntireAgent() string
 41→	PromptPattern() string
 42→	// TimeoutMultiplier returns a factor applied to per-test timeouts.
 43→	// Slower agents (e.g. Gemini) return values > 1.
 44→	TimeoutMultiplier() float64
 45→	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
 46→	StartSession(ctx context.Context, dir string) (Session, error)
 47→	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
 48→	// Called before any tests run. Implementations should be idempotent.
 49→	Bootstrap() error
 50→	// IsTransientError returns true if the error from RunPrompt looks like
 51→	// a transient API failure (e.g. 500, rate limit, network error) that
 52→	// is worth retrying.
 53→	IsTransientError(out Output, err error) bool
 54→}
 55→
 56→type Session interface {
 57→	Send(input string) error
 58→	WaitFor(pattern string, timeout time.Duration) (string, error)
 59→	Capture() string
 60→	Close() error
 61→}
 62→
 63→var registry []Agent
 64→var gates = map[string]chan struct{}{}
 65→
 66→func Register(a Agent) {
 67→	registry = append(registry, a)
 68→}
 69→
 70→// RegisterGate sets a concurrency limit for an agent's tests.
 71→// Tests call AcquireSlot/ReleaseSlot to respect this limit.
 72→// The limit can be overridden via E2E_CONCURRENT_TEST_LIMIT.
 73→func RegisterGate(name string, defaultMax int) {
 74→	max := defaultMax
 75→	if v, err := strconv.Atoi(os.Getenv("E2E_CONCURRENT_TEST_LIMIT")); err == nil && v > 0 {
 76→		max = v
 77→	}
 78→	gates[name] = make(chan struct{}, max)
 79→}
 80→
 81→// AcquireSlot blocks until a test slot is available for the agent or the
 82→// context is cancelled. Returns a non-nil error if the context expires
 83→// before a slot opens.
 84→func AcquireSlot(ctx context.Context, a Agent) error {
 85→	g, ok := gates[a.Name()]
 86→	if !ok {
 87→		return nil
 88→	}
 89→	select {
 90→	case g <- struct{}{}:
 91→		return nil
 92→	case <-ctx.Done():
 93→		return ctx.Err()
 94→	}
 95→}
 96→
 97→// ReleaseSlot frees a test slot for the agent.
 98→func ReleaseSlot(a Agent) {
 99→	if g, ok := gates[a.Name()]; ok {
100→		<-g
101→	}
102→}
103→
104→func All() []Agent {
105→	return registry
106→}
